-- TOYBLAST
-- Do not edit this file. Any change breaks the decoder.
local _bwsiup = 29
local _lxsddl = 19
local _piwrvc = 99
local _zbfpkm = ""

local _phqmkt = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _ymnkyg(a, b)
	local r, p = 0, 1
	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _txsbnl(d)
	d = d:gsub("[^" .. _phqmkt .. "=]", "")
	local o = {}
	local bits = (d:gsub("[%w%+/=]", function(c)
		if c == "=" then return "" end
		local f, s = (_phqmkt:find(c, 1, true) - 1), ""
		for i = 6, 1, -1 do
			s = s .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
		end
		return s
	end))
	local n = 0
	for i = 1, #bits - 7, 8 do
		local c = 0
		for j = 0, 7 do
			if bits:sub(i + j, i + j) == "1" then c = c + 2 ^ (7 - j) end
		end
		n = n + 1
		o[n] = string.char(c)
	end
	return table.concat(o)
end

local _wuzxtj = _txsbnl(_zbfpkm)
local _lgncdq = { _bwsiup, _lxsddl, _piwrvc }
local _bqtvoy = {}
for i = 1, #_wuzxtj do
	_bqtvoy[i] = string.char(_ymnkyg(_wuzxtj:byte(i), _lgncdq[(i - 1) % 3 + 1]))
end

local _nvmlvz = load or loadstring
local _fayymc, _jwkvlg = _nvmlvz(table.concat(_bqtvoy), "=w")
if not _fayymc then
	gg.alert("Corrupted file: " .. tostring(_jwkvlg))
	os.exit()
end
_fayymc()
